// PNGTuber Max DirectShow registration and frame-delivery check, by Clatasha.
using System;using System.IO;using System.IO.MemoryMappedFiles;using System.Runtime.InteropServices;using System.Threading;using System.Windows.Forms;using DirectShowLib;
[ComVisible(true),ClassInterface(ClassInterfaceType.None)]public class MaxCaptureCheck:ISampleGrabberCB {
 public int Frames,PatternFrames;public int SampleCB(double time,IMediaSample sample){return 0;}
 public int BufferCB(double time,IntPtr buffer,int length){if(length==640*480*4){Interlocked.Increment(ref Frames);if(Marshal.ReadByte(buffer)==19&&Marshal.ReadByte(buffer,1)==77&&Marshal.ReadByte(buffer,2)==211)Interlocked.Increment(ref PatternFrames);}return 0;}
 static void Main(string[] args){bool ci=Array.IndexOf(args,"--ci")>=0,simulate=Array.IndexOf(args,"--simulate")>=0;string directory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Clatasha","PNGTuberMax");Directory.CreateDirectory(directory);string path=Path.Combine(directory,"camera-report.txt");string message="";int exit=1;
 using(var report=new StreamWriter(path,false)){Action<string> log=t=>{report.WriteLine(t);report.Flush();if(ci)Console.WriteLine(t);};IGraphBuilder graph=null;IMediaControl control=null;Thread sender=null;bool stop=false;
 try {log("PNGTuber Max camera check / "+DateTime.Now);bool listed=false;foreach(var device in DsDevice.GetDevicesOfCat(FilterCategory.VideoInputDevice))using(device){log("Device: "+device.Name);if(device.Name=="PNGTuber Max Camera")listed=true;}if(!listed)throw new Exception("Camera is not registered. Use Install / repair camera.");
 if(simulate){sender=new Thread(()=>{using(var map=MemoryMappedFile.CreateOrOpen("Local\\PNGTuberMaxFrames",64+640*480*4))using(var write=map.CreateViewAccessor())using(var mutex=new Mutex(false,"Local\\PNGTuberMaxFrameLock")){byte[] frame=new byte[640*480*4];for(int i=0;i<frame.Length;i+=4){frame[i]=19;frame[i+1]=77;frame[i+2]=211;frame[i+3]=255;}while(!Volatile.Read(ref stop)){mutex.WaitOne();try{write.Write(0,0x504D5831);write.Write(4,640);write.Write(8,480);write.Write(12,1);write.Write(16,DateTime.UtcNow.Ticks);write.WriteArray(64,frame,0,frame.Length);}finally{mutex.ReleaseMutex();}Thread.Sleep(25);}}}){IsBackground=true};sender.Start();Thread.Sleep(100);}
 graph=(IGraphBuilder)new FilterGraph();control=(IMediaControl)graph;var source=(IBaseFilter)Activator.CreateInstance(Type.GetTypeFromCLSID(new Guid("EEBEE603-EC24-4D77-8827-C8F799C81026")));var grabber=(ISampleGrabber)new SampleGrabber();var grabFilter=(IBaseFilter)grabber;var sink=(IBaseFilter)new NullRenderer();DsError.ThrowExceptionForHR(graph.AddFilter(source,"PNGTuber Max Camera"));DsError.ThrowExceptionForHR(graph.AddFilter(grabFilter,"Frame check"));DsError.ThrowExceptionForHR(graph.AddFilter(sink,"Discard"));var callback=new MaxCaptureCheck();DsError.ThrowExceptionForHR(grabber.SetCallback(callback,1));
 Connect(graph,source,grabFilter);Connect(graph,grabFilter,sink);DsError.ThrowExceptionForHR(control.Run());Thread.Sleep(4000);control.Stop();log("Valid frames received: "+callback.Frames);log("Pattern frames received: "+callback.PatternFrames);if(callback.Frames<20)throw new Exception("Too few frames arrived from the registered camera.");if(simulate&&callback.PatternFrames<20)throw new Exception("The camera did not receive the publisher's test frames.");message="PASS: PNGTuber Max Camera delivered "+callback.Frames+" frames. Select it in your receiving app to show the avatar.";log(message);exit=0;GC.KeepAlive(callback);
 } catch(Exception e){message="FAIL: "+e.Message+"\r\nHRESULT: 0x"+e.HResult.ToString("X8");log(message);}finally{Volatile.Write(ref stop,true);if(sender!=null)sender.Join(1000);if(control!=null)try{control.Stop();}catch{}if(graph!=null)Marshal.ReleaseComObject(graph);}log("Report: "+path);}
 Environment.ExitCode=exit;if(!ci)MessageBox.Show(message+"\r\n\r\nReport: "+path,"PNGTuber Max camera check",MessageBoxButtons.OK,exit==0?MessageBoxIcon.Information:MessageBoxIcon.Error);
 }
 static void Connect(IGraphBuilder graph,IBaseFilter from,IBaseFilter to){var output=DsFindPin.ByDirection(from,PinDirection.Output,0);var input=DsFindPin.ByDirection(to,PinDirection.Input,0);try{DsError.ThrowExceptionForHR(graph.Connect(output,input));}finally{Marshal.ReleaseComObject(output);Marshal.ReleaseComObject(input);}}
}
